def transform(grid):
    """Translate the contents down one row, filling the top with top-left color."""
    h, w = len(grid), len(grid[0])
    background = grid[0][0]
    out = [[background] * w for _ in range(h)]
    for r in range(h - 1):
        for c in range(w):
            if grid[r][c] != background:
                out[r + 1][c] = grid[r][c]
    return out
